import { Dialog, DialogPanel, Transition } from '@headlessui/react';
import { Fragment, ReactNode, useCallback } from 'react';
import { useBlocker } from 'react-router-dom';

export type BottomSheetProps = {
  open: boolean;
  onClose: () => void;
  afterLeave?: () => void;
  children: ReactNode;
  title?: string | JSX.Element;
  description?: string | JSX.Element;
  centeredTitle?: boolean;
  showCloseButton?: boolean;
  preventCloseOnOutsideClick?: boolean;
};

const BottomSheet = ({
  open,
  onClose,
  afterLeave,
  children,
  title,
  showCloseButton = true,
  preventCloseOnOutsideClick = false,
}: BottomSheetProps) => {
  const whenToBlock = useCallback(() => open, [open]);
  const blocker = useBlocker(whenToBlock);
  const handleClose = useCallback(() => {
    blocker?.reset?.();
    onClose();
  }, []);

  const handleDialogClose = useCallback(() => {
    if (preventCloseOnOutsideClick) {
      return;
    }
    if (showCloseButton) {
      handleClose();
    }
  }, [preventCloseOnOutsideClick, showCloseButton, handleClose]);

  return (
    <Transition show={open} as={Fragment} afterLeave={afterLeave}>
      <Dialog onClose={handleDialogClose} className="bottom-sheet-overlay active">
        <DialogPanel as="div" className="bottom-sheet-container" data-testid="dialog-panel">
          <div className="bottom-sheet-header">
            <h3 className="bottom-sheet-title">{title}</h3>
            {showCloseButton && (
              <button type="button" className="btn-sheet-close" aria-label="닫기" onClick={handleClose} />
            )}
          </div>
          {children}
        </DialogPanel>
      </Dialog>
    </Transition>
  );
};

export { BottomSheet };
